cat > /tmp/gost_func.go << 'EOF'
// NewClient make Client by family
func NewClient(family string) Client {
	switch family {
	case cnf.RedHat, cnf.CentOS:
		return RedHat{}
	case cnf.Debian, cnf.Raspbian:
		return Debian{}
	case cnf.Windows:
		return Microsoft{}
	case cnf.Oracle:
		return RedHat{}
	default:
		return Pseudo{}
	}
}
EOF
